/// <summary>
/// getOpportunityCount's request, sent after a pick or putaway is confirmed at LocationId.
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountOpportunityRequest
{
    DataAreaId dataAreaId;
    str        userId;
    str        warehouseId;
    str        locationId;
    str        itemNumber;

}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

[DataMemberAttribute('UserId')]
public str parmUserId(str _value = userId)
{
    userId = _value;
    return userId;
}

[DataMemberAttribute('WarehouseId')]
public str parmWarehouseId(str _value = warehouseId)
{
    warehouseId = _value;
    return warehouseId;
}

[DataMemberAttribute('LocationId')]
public str parmLocationId(str _value = locationId)
{
    locationId = _value;
    return locationId;
}

[DataMemberAttribute('ItemNumber')]
public str parmItemNumber(str _value = itemNumber)
{
    itemNumber = _value;
    return itemNumber;
}
